ALTER TABLE public.listas_presenca ADD COLUMN IF NOT EXISTS instrutor_nome text;
ALTER TABLE public.listas_presenca ADD COLUMN IF NOT EXISTS instrutor_cargo text;
ALTER TABLE public.listas_presenca ADD COLUMN IF NOT EXISTS instrutor_assinatura text;
ALTER TABLE public.listas_presenca ADD COLUMN IF NOT EXISTS instrutor_assinatura_data timestamp with time zone;

CREATE OR REPLACE FUNCTION public.salvar_lista_treinamento(p_id uuid, p_dados jsonb, p_participantes jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$ DECLARE v_id uuid; v_owner uuid; v_company uuid; p jsonb; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sessão expirada'; END IF; IF jsonb_typeof(p_participantes)<>'array' THEN RAISE EXCEPTION 'Participantes inválidos'; END IF; IF p_id IS NULL THEN v_owner:=auth.uid(); v_company:=public.active_company_id(); INSERT INTO public.listas_presenca(user_id,company_id,tema) VALUES(v_owner,v_company,'') RETURNING id INTO v_id; ELSE SELECT id,user_id,company_id INTO v_id,v_owner,v_company FROM public.listas_presenca WHERE id=p_id FOR UPDATE; IF v_id IS NULL OR (v_owner<>auth.uid() AND NOT public.is_admin_principal(auth.uid())) THEN RAISE EXCEPTION 'Sem permissão para editar esta lista'; END IF; END IF; IF trim(coalesce(p_dados->>'nome_treinamento',''))='' THEN RAISE EXCEPTION 'Informe o nome do treinamento'; END IF; UPDATE public.listas_presenca SET local=nullif(trim(p_dados->>'local'),''),data=nullif(p_dados->>'data','')::date,empresa=upper(nullif(trim(p_dados->>'empresa'),'')),horario=nullif(p_dados->>'horario',''),horario_inicial=nullif(p_dados->>'horario_inicial',''),horario_final=nullif(p_dados->>'horario_final',''),carga_horaria=nullif(p_dados->>'carga_horaria',''),tema=upper(trim(coalesce(p_dados->>'tema',''))),nome_treinamento=upper(trim(p_dados->>'nome_treinamento')),modo_assinatura=coalesce(p_dados->>'modo_assinatura','manual'),instrutor_nome=upper(nullif(trim(coalesce(p_dados->>'instrutor_nome','')),'')),instrutor_cargo=upper(nullif(trim(coalesce(p_dados->>'instrutor_cargo','')),'')) WHERE id=v_id; DELETE FROM public.lista_presenca_participantes WHERE lista_id=v_id AND id NOT IN(SELECT (x->>'id')::uuid FROM jsonb_array_elements(p_participantes) x WHERE nullif(x->>'id','') IS NOT NULL); FOR p IN SELECT value FROM jsonb_array_elements(p_participantes) LOOP IF trim(coalesce(p->>'nome',''))='' THEN RAISE EXCEPTION 'Informe o nome do participante'; END IF; IF nullif(p->>'employee_id','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.employees WHERE id=(p->>'employee_id')::uuid AND company_id=v_company) THEN RAISE EXCEPTION 'Colaborador não pertence à empresa da lista'; END IF; IF nullif(p->>'id','') IS NOT NULL THEN UPDATE public.lista_presenca_participantes SET nome=upper(trim(p->>'nome')),funcao=upper(nullif(trim(p->>'funcao'),'')),ordem=(p->>'ordem')::integer WHERE id=(p->>'id')::uuid AND lista_id=v_id; IF NOT FOUND THEN RAISE EXCEPTION 'Participante inválido'; END IF; ELSE INSERT INTO public.lista_presenca_participantes(lista_id,user_id,company_id,employee_id,ordem,nome,funcao) VALUES(v_id,v_owner,v_company,nullif(p->>'employee_id','')::uuid,(p->>'ordem')::integer,upper(trim(p->>'nome')),upper(nullif(trim(p->>'funcao'),''))); END IF; END LOOP; RETURN v_id; END $function$;